<?php
require __DIR__ . '/app/bootstrap.php';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';if($action==='remove'){unset($_SESSION['cart'][(int)($_POST['id']??0)]);flash('success','محصول از سبد حذف شد.');}elseif($action==='update'){foreach(($_POST['qty']??[]) as $id=>$qty){$id=(int)$id;$qty=(int)$qty;if($qty<1)unset($_SESSION['cart'][$id]);else $_SESSION['cart'][$id]=min(99,$qty);}flash('success','سبد خرید به‌روزرسانی شد.');}header('Location: '.site_url('cart.php'));exit;}
$items=get_cart_items($pdo);$total=cart_total($items);render_header('سبد خرید');
?>
<main class="container"><div class="page-title"><h1>سبد خرید</h1><p>پیش از ادامه، تعداد محصولات را بررسی کنید.</p></div>
<?php if(!$items): ?><div class="empty">سبد خرید شما خالی است.<p><a class="btn" href="<?=e(site_url('products.php'))?>">مشاهده محصولات</a></p></div><?php else: ?>
<form method="post"><?=csrf_field()?><input type="hidden" name="action" value="update"><div class="table-wrap"><table class="table"><thead><tr><th>محصول</th><th>قیمت واحد</th><th>تعداد</th><th>جمع</th><th></th></tr></thead><tbody><?php foreach($items as $p): ?><tr><td><img src="<?=e(product_image($p['image']))?>" alt="" style="width:60px;height:50px;object-fit:cover;vertical-align:middle;border-radius:7px"> <?=e($p['name'])?></td><td><?=money($p['unit_price']??$p['price'])?><?php if(!empty($p['selected_options'])):?><small style="display:block"><?php foreach($p['selected_options'] as $op) echo e($op['option_name']).' ';?></small><?php endif;?></td><td><input class="qty" type="number" min="0" max="99" name="qty[<?=$p['id']?>]" value="<?=$p['qty']?>"></td><td><?=money($p['line_total'])?></td><td><button class="small-btn" type="submit" form="remove-<?=$p['id']?>">حذف</button></td></tr><?php endforeach; ?></tbody></table></div><p><button class="btn secondary">به‌روزرسانی سبد</button></p></form>
<?php foreach($items as $p): ?><form id="remove-<?=$p['id']?>" method="post" style="display:none"><?=csrf_field()?><input name="action" value="remove"><input name="id" value="<?=$p['id']?>"></form><?php endforeach; ?>
<div class="form-card" style="margin-right:0"><h2>جمع سفارش: <span class="price"><?=money($total)?></span></h2><p class="muted">هزینه ارسال و تخفیف در مرحله نهایی محاسبه می‌شوند.</p><a class="btn" href="<?=e(site_url('checkout.php'))?>">ادامه و ثبت سفارش</a></div>
<?php endif; ?></main><?php render_footer(); ?>
